            "gen_ai.tool.call.result": "{\"id\":\"client-onboarding\",\"description\":\"Onboards a new client: scaffolds the client's onboarding folder in the workspace, has the code agent generate and write the standard onboarding package (client profile, onboarding checklist, and welcome email draft), and returns a completion summary.\",\"status\":\"active\",\"inputSchema\":\"{\\\"$schema\\\": \\\"https://json-schema.org/draft/2020-12/schema\\\", \\\"additionalProperties\\\": false, \\\"properties\\\": {\\\"clientName\\\": {\\\"description\\\": \\\"Name of the new client, used as the workspace folder name (e.g. \\\\\\\"Acme Corp\\\\\\\").\\\", \\\"type\\\": \\\"string\\\"}, \\\"contactEmail\\\": {\\\"description\\\": \\\"Optional primary contact email for the client, used to personalize the onboarding documents.\\\", \\\"type\\\": \\\"string\\\"}, \\\"engagementSummary\\\": {\\\"description\\\": \\\"Optional one-paragraph description of the services or project the client signed up for.\\\", \\\"type\\\": \\\"string\\\"}}, \\\"required\\\": [\\\"clientName\\\"], \\\"type\\\": \\\"object\\\"}\",\"outputSchema\":\"{\\\"$schema\\\": \\\"https://json-schema.org/draft/2020-12/schema\\\", \\\"additionalProperties\\\": false, \\\"properties\\\": {\\\"clientFolder\\\": {\\\"description\\\": \\\"Workspace folder holding the client's onboarding documents.\\\", \\\"type\\\": \\\"string\\\"}, \\\"clientName\\\": {\\\"description\\\": \\\"The onboarded client's name.\\\", \\\"type\\\": \\\"string\\\"}, \\\"report\\\": {\\\"description\\\": \\\"Agent's summary of the onboarding documents it created.\\\", \\\"type\\\": \\\"string\\\"}, \\\"status\\\": {\\\"description\\\": \\\"Completion status of the onboarding run.\\\", \\\"type\\\": \\\"string\\\"}}, \\\"required\\\": [\\\"clientName\\\", \\\"clientFolder\\\", \\\"status\\\", \\\"report\\\"], \\\"type\\\": \\\"object\\\"}\",\"graph\":[{\"type\":\"mapping\",\"id\":\"client-dir-config\",\"description\":\"Build the mkdir input from the workflow's clientName input field.\",\"mapConfig\":\"{\\\"path\\\":{\\\"template\\\":\\\"clients/${initData.clientName}/onboarding\\\"},\\\"recursive\\\":{\\\"value\\\":true}}\"},{\"type\":\"tool\",\"id\":\"create-client-folder\",\"toolId\":\"mkdir\",\"description\":\"Scaffold the clients/<clientName>/onboarding folder in the workspace.\"},{\"type\":\"mapping\",\"id\":\"to-docgen-prompt\",\"description\":\"Build the code agent's required { prompt } input from the workflow's original input fields.\",\"mapConfig\":\"{\\\"prompt\\\":{\\\"template\\\":\\\"You are onboarding a new client by preparing their workspace files.\\\\n\\\\nClient name: ${initData.clientName}\\\\nContact email: ${initData.contactEmail}\\\\nEngagement summary: ${initData.engagementSummary}\\\\n\\\\nThe folder clients/${initData.clientName}/onboarding has already been created for you.\\\\n\\\\nCreate EXACTLY these three Markdown documents inside clients/${initData.clientName}/onboarding/:\\\\n1. client-profile.md - a client profile: who the client is, the engagement summary, key contacts, and agreed next steps.\\\\n2. onboarding-checklist.md - a step-by-step onboarding checklist with phases, owners, and target day offsets (Day 1, Day 3, and so on).\\\\n3. welcome-email.md - a ready-to-send welcome email draft addressed to the client contact.\\\\n\\\\nRules:\\\\n- Personalize every document with the client name, contact email, and engagement summary.\\\\n- Use complete, well-structured Markdown content.\\\\n- Create ONLY these three files inside clients/${initData.clientName}/onboarding/. Do not modify or delete anything else, and do not run any commands other than what is needed to write these files.\\\\n\\\\nWhen finished, reply with a concise summary listing each file you created with a one-line description of its contents. Do not paste full file contents in your reply.\\\"}}\"},{\"type\":\"agent\",\"id\":\"generate-and-write-docs\",\"agentId\":\"code-agent\",\"description\":\"Generate the three personalized onboarding documents and write them into the client's onboarding folder.\"},{\"type\":\"mapping\",\"id\":\"finalize\",\"description\":\"Collapse the run into the final completion summary.\",\"mapConfig\":\"{\\\"clientName\\\":{\\\"template\\\":\\\"${initData.clientName}\\\"},\\\"clientFolder\\\":{\\\"template\\\":\\\"clients/${initData.clientName}\\\"},\\\"status\\\":{\\\"value\\\":\\\"complete\\\"},\\\"report\\\":{\\\"template\\\":\\\"Onboarding package written to clients/${initData.clientName}/onboarding. Agent report: ${stepResults.generate-and-write-docs.text}\\\"}}\"}]}",
